using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using EqlTracker.Core;

internal static class UpdateTests
{
    internal static void Register(Action<string, Action> test)
    {
        void Check(bool value) { if (!value) throw new Exception("Update assertion failed."); }
        void Reject(Action action) { try { action(); } catch (Exception e) when (e is InvalidDataException or CryptographicException or FormatException or IOException) { return; } throw new Exception("Unsafe input was accepted."); }
        UpdateManifest Manifest() => new(1,"EQL Catalyst",UpdateProtocol.Repository,"1.4.0-beta.1","v1.4.0-beta.1",new string('a',40),"win-x64","1.4.0-beta.1",[new("Installer","EQL-Catalyst-1.4.0-beta.1-win-x64-setup.exe",10,new string('a',64)),new("Portable","EQL-Catalyst-1.4.0-beta.1-win-x64.zip",10,new string('b',64))]);
        test("Updates require explicit consent; weekly schedule and retry delay",()=>{var p=new UpdatePreferences();var now=DateTimeOffset.UtcNow;Check(!p.Due(now));p.Automatic=true;Check(p.Due(now));p.LastChecked=now.AddDays(-6);Check(!p.Due(now));p.LastChecked=now.AddDays(-7);Check(p.Due(now));p.LastAttempt=now.AddHours(-1);Check(!p.Due(now));p.LastAttempt=now.AddHours(-6);Check(p.Due(now));});
        foreach(var (candidate,current,newer) in new[]{("1.4.0-beta.1","1.1.0-beta.1",true),("1.4.0-beta.2","1.4.0-beta.1",true),("1.4.0","1.4.0-beta.9",true),("1.4.0-beta.1","1.4.0",false),("1.4.0-beta.1","1.4.0-beta.1+build",false),("1.3.9","1.4.0-beta.1",false)})
            test("Update version ordering "+candidate+" versus "+current,()=>Check(UpdateProtocol.Newer(candidate,current)==newer));
        foreach(string invalid in new[]{"main","1.4","1.4.0-alpha.1","1.4.0-beta.bad","9999999999999.1.1"})test("Reject unsupported update version "+invalid,()=>{try{_ = UpdateVersion.Parse(invalid);}catch(Exception e)when(e is InvalidDataException or OverflowException){return;}throw new Exception("Invalid version accepted");});
        test("Signed manifest authenticates exact bytes",()=>{using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);var bytes=JsonSerializer.SerializeToUtf8Bytes(Manifest());var signature=key.SignData(bytes,HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation);Check(UpdateProtocol.Verify(bytes,signature,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())).Version=="1.4.0-beta.1");bytes[0]^=1;Reject(()=>UpdateProtocol.Verify(bytes,signature,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())));});
        test("Forged and missing manifest signatures fail closed",()=>{using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);byte[] bytes=JsonSerializer.SerializeToUtf8Bytes(Manifest());Reject(()=>UpdateProtocol.Verify(bytes,new byte[64]));Reject(()=>UpdateProtocol.Verify(bytes,[]));});
        foreach(string field in new[]{"repository","schema","architecture","tag","package","size","minimum"})test("Reject signed but invalid manifest "+field,()=>{using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);var m=Manifest();m=field switch{"repository"=>m with{Repository="example/other"},"schema"=>m with{Schema=99},"architecture"=>m with{Architecture="linux-x64"},"tag"=>m with{Tag="v1.3.0"},"package"=>m with{Packages=[]},"size"=>m with{Packages=[m.Packages[0] with{Bytes=-1},m.Packages[1]]},_=>m with{MinimumUpdaterVersion="bad"}};var bytes=JsonSerializer.SerializeToUtf8Bytes(m);Reject(()=>UpdateProtocol.Verify(bytes,key.SignData(bytes,HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation),Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())));});
        foreach(string url in new[]{"http://github.com/file","https://github.com.example/file","https://example.org/file","https://user@github.com/file","https://github.com:444/file"})test("Reject untrusted update URI "+url.Split('/')[0],()=>Check(!UpdateProtocol.TrustedUri(new(url))));
        test("Allow bounded GitHub release CDN hosts",()=>Check(UpdateProtocol.TrustedUri(new("https://release-assets.githubusercontent.com/file"))&&UpdateProtocol.TrustedUri(new("https://api.github.com/repos/Runelaron/EQL-Catalyst/releases"))));
        foreach(string relative in new[]{"../escape","/absolute","C:/outside","folder\\escape","a/../b","a//b"})test("Reject unsafe update path "+relative,()=>Reject(()=>UpdateFiles.Child(Path.GetTempPath(),relative)));
        test("Update preferences persist independently from character state",()=>InTemp(root=>{var p=new UpdatePreferences{Automatic=true,HighestVersion="1.4.0-beta.1"};p.Save(root);var q=UpdatePreferences.Read(root);Check(q.Automatic&&q.HighestVersion==p.HighestVersion&&Directory.GetFiles(root).Length==2);File.WriteAllText(Path.Combine(root,"update-preferences.json"),"invalid");Check(!UpdatePreferences.Read(root).Automatic);}));
        test("Stale update checkpoints cannot undo another character's opt-out",()=>InTemp(root=>{new UpdatePreferences{Automatic=true}.Save(root,true);var stale=UpdatePreferences.Read(root);var changed=UpdatePreferences.Read(root);changed.Automatic=false;changed.Save(root,true);stale.LastChecked=DateTimeOffset.UtcNow;stale.Save(root);var saved=UpdatePreferences.Read(root);Check(!saved.Automatic&&saved.LastChecked==stale.LastChecked);}));
        test("Package checksum and size reject partial or changed downloads",()=>InTemp(root=>{string path=Path.Combine(root,"package");File.WriteAllText(path,"exact");var p=new UpdatePackage("Portable","package",5,Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path))));UpdateProtocol.VerifyFile(path,p);File.WriteAllText(path,"other");Reject(()=>UpdateProtocol.VerifyFile(path,p));File.WriteAllText(path,"x");Reject(()=>UpdateProtocol.VerifyFile(path,p));}));
        test("Portable replacement preserves unrelated files and keeps recovery snapshot",()=>InTemp(root=>{string app=Path.Combine(root,"app"),payload=Path.Combine(root,"new");Payload(app,"old");File.WriteAllText(Path.Combine(app,"personal.txt"),"preserve");Payload(payload,"new");string backup=UpdateInstallation.ReplacePortable(app,payload,Path.Combine(root,"journal.json"));Check(File.ReadAllText(Path.Combine(app,"EQLTracker.exe"))=="new"&&File.ReadAllText(Path.Combine(app,"personal.txt"))=="preserve"&&File.ReadAllText(Path.Combine(backup,"EQLTracker.exe"))=="old");}));
        test("Interrupted portable directory replacement recovers original",()=>InTemp(root=>{string app=Path.Combine(root,"app"),backup=app+".backup-test";Payload(backup,"original");string journal=Path.Combine(root,"journal.json");UpdateFiles.WriteJson(journal,new UpdateJournal(app,app+".update-test",backup,"Prepared"));Check(UpdateInstallation.Recover(journal)&&File.ReadAllText(Path.Combine(app,"EQLTracker.exe"))=="original");}));
        test("Extracted helper tampering cannot be hidden by a modified file manifest",()=>InTemp(root=>{string payload=Path.Combine(root,"payload");Payload(payload,"new");string zip=Path.Combine(root,"package.zip");ZipFile.CreateFromDirectory(payload,zip); // Use the real package's single-root structure.
            string folder=Path.Combine(root,"container");Directory.CreateDirectory(folder);UpdateInstallation.CopyTree(payload,Path.Combine(folder,"release"));File.Delete(zip);ZipFile.CreateFromDirectory(folder,zip);UpdateInstallation.VerifyExtracted(zip,payload);Payload(payload,"tampered");Reject(()=>UpdateInstallation.VerifyExtracted(zip,payload));}));
        test("Archive traversal and duplicated paths are rejected before extraction",()=>InTemp(root=>{string zip=Path.Combine(root,"bad.zip");using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create)){using var writer=new StreamWriter(archive.CreateEntry("../outside").Open());writer.Write("bad");}Reject(()=>UpdateInstallation.Extract(zip,Path.Combine(root,"extracted")));Check(!File.Exists(Path.Combine(root,"outside")));}));
    }
    private static void InTemp(Action<string> action)
    {string root=Path.Combine(Path.GetTempPath(),"eql-update-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{action(root);}finally{Directory.Delete(root,true);}}
    private static void Payload(string root,string value)
    {Directory.CreateDirectory(root);foreach(string file in new[]{"EQLTracker.exe","EQLUpdater.exe"})File.WriteAllText(Path.Combine(root,file),value);UpdateFiles.WriteJson(Path.Combine(root,"release-manifest.json"),new{Product="EQL Catalyst",Version="1.4.0-beta.1",Files=Directory.GetFiles(root).Where(p=>!p.EndsWith("release-manifest.json")).ToDictionary(p=>Path.GetFileName(p)!,p=>Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(p))))});}
}
